cards.starterCode:
// === ongkir.js ===
function hitungOngkir(km) {
  return km <= 3 ? 8000 : 8000 + (km - 3) * 2500;
}
module.exports = { hitungOngkir };
// === main.js ===
const { hitungOngkir } = require("./ongkir.js");
console.log(hitungOngkir(2));
console.log(hitungOngkir(7));

